import { renderToString } from "react-dom/server";
import { describe, expect, it } from "vitest";
import EntityCard from "./EntityCard.js";

describe("EntityCard SSR", () => {
  it("renders a real link to a homed entity, so it navigates without scripts", () => {
    const html = renderToString(<EntityCard href="#layout" title="Layout" />);
    expect(html).toContain("ds entity-card");
    expect(html).toContain(
      '<h3 class="title"><a class="link" href="#layout">Layout</a></h3>',
    );
  });

  it("renders inert text for an entity without a home", () => {
    const html = renderToString(<EntityCard title="Layout" />);
    expect(html).toContain('<h3 class="title">Layout</h3>');
    expect(html).not.toContain("<a");
  });
});
